ark:59853/software-samtoolssort-ee6c604.description:
task SamtoolsSort {
    input {
        String sample
        File bam
    }

    command <<<
        set -euo pipefail
        samtools sort -T ~{sample} -O bam ~{bam} > ~{sample}.sorted.bam
    >>>

    output {
        File sorted_bam = "~{sample}.sorted.bam"
    }
}

ark:59853/software-samtoolsindex-3eb355e.description:
task SamtoolsIndex {
    input {
        String sample
        File bam
    }

    command <<<
        set -euo pipefail
        # the index has to sit beside the bam it indexes
        ln -s ~{bam} ~{sample}.sorted.bam
        samtools index ~{sample}.sorted.bam
    >>>

    output {
        File index = "~{sample}.sorted.bam.bai"
    }
}
